with open(HERE / "router-200.jsonl", "w") as f:
    for i, r in enumerate(R, 1):
        t, d, web, vis, tools, prompt = r[:6]
        att = r[6] if len(r) > 6 else []
        assert not web or tools, prompt
        assert vis == (1 if att else 0), prompt
        f.write(json.dumps({"id": f"r{i:03d}", "prompt": prompt, "attachments": att,
                            "labels": {"a": {"task_type": t, "difficulty": d, "needs_web": bool(web), "needs_vision": bool(vis), "needs_tools": bool(tools)}}},
                           ensure_ascii=False) + "\n")
with open(HERE / "noul-40.jsonl", "w") as f:
    for i, (state, q, yes) in enumerate(N, 1):
        f.write(json.dumps({"id": f"n{i:02d}", "state": state, "question": q, "expected": yes}, ensure_ascii=False) + "\n")

